sqlite3 -json "/data/arabic_dict.db" "SELECT e.id AS entry_id, e.dictionary_id, e.headword, e.headword_norm, e.root, e.root_source, e.pos, e.definitions_text, e.translation_en, e.domain, d.key AS dict_key, d.name_ar AS dict_name_ar, d.source_type, d.period, d.author, d.death_year FROM entries e JOIN dictionaries d ON e.dictionary_id = d.id WHERE e.headword_norm IN ('استعداد','الاستعداد','ميل','الميل','نزعة','النزعة','سجية','السجية','طبع','الطبع','جبلة','الجبلة','شيمة','الشيمة') ORDER BY e.headword_norm, d.source_type, d.death_year ASC NULLS LAST;" 2>/dev/null | python3 -c "
import json,sys
data=json.load(sys.stdin)
# Group by headword_norm
from collections import defaultdict
groups=defaultdict(list)
for r in data:
    groups[r['headword_norm']].append(r)
for hw,rows in sorted(groups.items()):
    print(f'\n=== {hw} ({len(rows)} entries) ===')
    for r in rows[:4]:
        print(f'  id={r[\"entry_id\"]} dict={r[\"dict_name_ar\"]} src={r[\"source_type\"]} root={r[\"root\"]}({r[\"root_source\"]}) pos={r[\"pos\"]}')
        if r['definitions_text']:
            print(f'  def={r[\"definitions_text\"][:200]}')
        if r['translation_en']:
            print(f'  en={r[\"translation_en\"]}')
    if len(rows)>4:
        print(f'  ... +{len(rows)-4} more')
print(f'\nTotal: {len(data)} entries')
" 2>/dev/null
